// Package connect is a Connect protocol client for unary calls with the JSON
// codec, the transport behind services generated by protoc-gen-goalchemy.
// It follows connectrpc.com/connect: requests are POSTed as
// application/json with Connect-Protocol-Version 1 and Connect-Timeout-Ms,
// and error responses become *Error with the codes, messages and details
// connect-go reports. Calls suspend on the host HTTP client, so programs use
// the cooperative gate.
package connect

import (
	"github.com/eugenioenko/goalchemy/lib/context"
	"github.com/eugenioenko/goalchemy/lib/http"
	"github.com/eugenioenko/goalchemy/std/encoding/jsonvalue"
	"github.com/eugenioenko/goalchemy/std/encoding/protojson"
	"github.com/eugenioenko/goalchemy/std/errors"
	"github.com/eugenioenko/goalchemy/std/strconv"
	"github.com/eugenioenko/goalchemy/std/strings"
)

// Code is a Connect error code.
type Code uint32

const (
	CodeCanceled           Code = 1
	CodeUnknown            Code = 2
	CodeInvalidArgument    Code = 3
	CodeDeadlineExceeded   Code = 4
	CodeNotFound           Code = 5
	CodeAlreadyExists      Code = 6
	CodePermissionDenied   Code = 7
	CodeResourceExhausted  Code = 8
	CodeFailedPrecondition Code = 9
	CodeAborted            Code = 10
	CodeOutOfRange         Code = 11
	CodeUnimplemented      Code = 12
	CodeInternal           Code = 13
	CodeUnavailable        Code = 14
	CodeDataLoss           Code = 15
	CodeUnauthenticated    Code = 16
)

var codeNames = []string{"", "canceled", "unknown", "invalid_argument", "deadline_exceeded", "not_found", "already_exists",
	"permission_denied", "resource_exhausted", "failed_precondition", "aborted", "out_of_range", "unimplemented",
	"internal", "unavailable", "data_loss", "unauthenticated"}

// String returns the code's wire name, such as "not_found".
func (c Code) String() string {
	if c >= 1 && int(c) < len(codeNames) {
		return codeNames[c]
	}
	return "code_" + strconv.FormatUint(uint64(c), 10)
}

func codeFromName(name string) (Code, bool) {
	for i := 1; i < len(codeNames); i++ {
		if codeNames[i] == name {
			return Code(i), true
		}
	}
	return 0, false
}

// ErrorDetail is one entry of an error's details: a protobuf message packed
// as its type URL and binary encoding, with an optional JSON debug form.
type ErrorDetail struct {
	TypeURL string
	Value   []byte
	Debug   jsonvalue.Value
}

// Error is a failed call. Meta holds the response headers as alternating
// names and values.
type Error struct {
	Code    Code
	Message string
	Details []*ErrorDetail
	Meta    []string
}

func (e *Error) Error() string {
	if e.Message == "" {
		return e.Code.String()
	}
	return e.Code.String() + ": " + e.Message
}

// CodeOf returns the code of a *Error in err's chain, CodeUnknown for other
// errors and 0 for nil.
func CodeOf(err error) Code {
	if err == nil {
		return 0
	}
	var e *Error
	if errors.As(err, &e) {
		return e.Code
	}
	return CodeUnknown
}

// Client calls one Connect server. Headers are sent with every call as
// alternating names and values.
type Client struct {
	BaseURL          string
	Headers          []string
	TimeoutMillis    int64
	MaxResponseBytes int
	// Transport holds lib/http.DoWith options, such as a client certificate
	// or extra root CAs.
	Transport []string
}

// DefaultTimeoutMillis bounds calls of a client whose TimeoutMillis is zero.
const DefaultTimeoutMillis = 30000

// DefaultMaxResponseBytes bounds responses of a client whose MaxResponseBytes
// is zero.
const DefaultMaxResponseBytes = 16 << 20

// NewClient returns a client for the server at baseURL, such as
// "https://platform.example.com".
func NewClient(baseURL string) *Client {
	return &Client{BaseURL: strings.TrimSuffix(baseURL, "/")}
}

func header(headers []string, name string) string {
	for i := 0; i+1 < len(headers); i += 2 {
		if strings.EqualFold(headers[i], name) {
			return headers[i+1]
		}
	}
	return ""
}

var statusText = map[int]string{
	400: "Bad Request", 401: "Unauthorized", 403: "Forbidden", 404: "Not Found", 405: "Method Not Allowed",
	408: "Request Timeout", 409: "Conflict", 412: "Precondition Failed", 413: "Request Entity Too Large",
	415: "Unsupported Media Type", 429: "Too Many Requests", 499: "", 500: "Internal Server Error",
	501: "Not Implemented", 502: "Bad Gateway", 503: "Service Unavailable", 504: "Gateway Timeout",
}

func statusLine(status int) string {
	return strconv.Itoa(status) + " " + statusText[status]
}

func httpToCode(status int) Code {
	switch status {
	case 400:
		return CodeInternal
	case 401:
		return CodeUnauthenticated
	case 403:
		return CodePermissionDenied
	case 404:
		return CodeUnimplemented
	case 429, 502, 503, 504:
		return CodeUnavailable
	}
	return CodeUnknown
}

func isJSON(contentType string) bool {
	return contentType == "application/json" || contentType == "application/json; charset=utf-8"
}

func decodeBinary(s string) ([]byte, bool) {
	v := jsonvalue.String(s)
	d := &protojson.Decoder{}
	if strings.ContainsAny(s, "-_") || strings.Contains(s, "=") && len(s)%4 != 0 {
		return nil, false
	}
	b := d.Bytes(v, "value")
	return b, d.Err() == nil
}

// wireError parses a Connect error body. ok is false when the body is not a
// valid error, in which case the HTTP status decides the code.
func wireError(body []byte) (*Error, bool) {
	v, err := jsonvalue.Parse(body)
	if err != nil || v.Kind() != jsonvalue.KindObject {
		return nil, false
	}
	e := &Error{}
	if c, found := v.Lookup("code"); found && !c.IsNull() {
		name, isString := c.AsString()
		if !isString {
			return nil, false
		}
		code, known := codeFromName(name)
		if !known {
			return nil, false
		}
		e.Code = code
	}
	if m, found := v.Lookup("message"); found && !m.IsNull() {
		s, isString := m.AsString()
		if !isString {
			return nil, false
		}
		e.Message = s
	}
	if ds, found := v.Lookup("details"); found && !ds.IsNull() {
		if ds.Kind() != jsonvalue.KindArray {
			return nil, false
		}
		for i := 0; i < ds.Len(); i++ {
			d := ds.Index(i)
			if d.Kind() != jsonvalue.KindObject {
				return nil, false
			}
			typ, okType := d.Get("type").AsString()
			value, okValue := d.Get("value").AsString()
			if d.Has("type") && !okType || d.Has("value") && !okValue {
				return nil, false
			}
			b, okB64 := decodeBinary(value)
			if !okB64 {
				return nil, false
			}
			if !strings.Contains(typ, "/") {
				typ = "type.googleapis.com/" + typ
			}
			e.Details = append(e.Details, &ErrorDetail{TypeURL: typ, Value: b, Debug: d.Get("debug")})
		}
	}
	return e, true
}

func transportError(ctx context.Context, err error) *Error {
	switch {
	case ctx.Err() == context.Canceled || errors.Is(err, context.Canceled):
		return &Error{Code: CodeCanceled, Message: err.Error()}
	case ctx.Err() == context.DeadlineExceeded || errors.Is(err, context.DeadlineExceeded):
		return &Error{Code: CodeDeadlineExceeded, Message: err.Error()}
	}
	return &Error{Code: CodeUnavailable, Message: err.Error()}
}

// CallUnary sends req to procedure, such as
// "/policy.attributes.AttributesService/GetAttribute", and decodes the reply
// into resp. headers are added to the client's for this call. It returns the
// response headers.
func (c *Client) CallUnary(ctx context.Context, procedure string, req, resp protojson.Message, headers []string) ([]string, error) {
	if ctx.Err() != nil {
		return nil, transportError(ctx, ctx.Err())
	}
	body, err := protojson.Marshal(req)
	if err != nil {
		return nil, &Error{Code: CodeInternal, Message: "marshal message: " + err.Error()}
	}
	timeout := c.TimeoutMillis
	if timeout == 0 {
		timeout = DefaultTimeoutMillis
	}
	limit := c.MaxResponseBytes
	if limit == 0 {
		limit = DefaultMaxResponseBytes
	}
	h := []string{"Content-Type", "application/json", "Connect-Protocol-Version", "1",
		"Connect-Timeout-Ms", strconv.FormatInt(timeout, 10)}
	h = append(h, c.Headers...)
	h = append(h, headers...)
	status, meta, reply, err := http.DoWith(ctx, "POST", c.BaseURL+procedure, h, body, limit, timeout, c.Transport)
	if err != nil {
		return nil, transportError(ctx, err)
	}
	contentType := header(meta, "Content-Type")
	if status != 200 {
		if isJSON(contentType) {
			if e, ok := wireError(reply); ok {
				if e.Code == 0 {
					e.Code = httpToCode(status)
				}
				e.Meta = meta
				return meta, e
			}
		}
		return meta, &Error{Code: httpToCode(status), Message: statusLine(status), Meta: meta}
	}
	if !isJSON(contentType) {
		code := CodeInternal
		if !strings.HasPrefix(contentType, "application/") {
			code = CodeUnknown
		}
		return meta, &Error{Code: code, Message: "invalid content-type: " + strconv.Quote(contentType) + "; expecting \"application/json\"", Meta: meta}
	}
	if err := protojson.Unmarshal(reply, resp); err != nil {
		return meta, &Error{Code: CodeInvalidArgument, Message: "unmarshal message: " + err.Error(), Meta: meta}
	}
	return meta, nil
}
